/* JavaScript Node ACM模式 控制台输入获取 */
const readline = require("readline");

const rl = readline.createInterface({
  input: process.stdin,
  output: process.stdout,
});

const lines = [];
let n;
rl.on("line", (line) => {
  lines.push(line);

  if (lines.length == 1) {
    n = lines[0] - 0;
  }

  if (n && lines.length == n + 1) {
    lines.shift();
    const tmp = lines.map((line) => line.split(" ").map(Number));
    console.log(getResult(tmp));
    lines.length = 0;
  }
});

function getResult(lines) {
  // 记录每个图形的边长
  const ans = [];

  // 定义一个64*64的矩阵
  const matrix = new Array(64).fill(0).map(() => new Array(64).fill(0));

  // 向64*64的矩阵中填充数字
  for (let line of lines) {
    // 每行第一个数是矩阵单元格填充的数字
    const num = line[0];

    // 后续每两个一组，表示填充该数字的单元格坐标
    for (let i = 1; i < line.length; i += 2) {
      const x = line[i];
      const y = line[i + 1];
      matrix[x][y] = num; // 填充数字
    }
  }

  const offsets = [
    [-1, 0],
    [1, 0],
    [0, -1],
    [0, 1],
  ];

  // 遍历每个图形的坐标
  for (let line of lines) {
    const num = line[0];
    let p = 0; // 周长

    for (let i = 1; i < line.length; i += 2) {
      const x = line[i];
      const y = line[i + 1];

      // 遍历图形中元素的上下左右
      for (let [offsetX, offsetY] of offsets) {
        const newX = x + offsetX;
        const newY = y + offsetY;

        // 如果图形元素的上或下或左或右没有越界
        if (newX >= 0 && newX < 64 && newY >= 0 && newY < 64) {
          // 则如果图形元素的上或下或左或右不是图形值，那么当前图形的边长+1
          if (matrix[newX][newY] != num) p++;
        } else {
          // 如果图形元素的上或下或左或右越界了，则当前图形边长也+1
          p++;
        }
      }
    }

    ans.push(p);
  }

  return ans.join(" ");
}

