#include <stdio.h>
#include <stdlib.h>

// 链表节点
typedef struct ListNode {
    int x; // 点的横坐标
    int y; // 点的纵坐标
    struct ListNode* next;
} ListNode;

// 链表
typedef struct LinkedList {
    int size;
    ListNode* head;
    ListNode* tail;
} LinkedList;

// 创建和初始化链表
LinkedList* new_LinkedList();
// 尾插节点
void add_LinkedList(LinkedList* link, int x, int y);

// 上，下，左，右 四个方向的偏移量
int offsets[4][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

int main() {
    // N个图形
    int n;
    scanf("%d", &n);

    // res数组记录每个图形的周长
    int res[n];

    // 64x64矩阵
    int matrix[64][64] = {0};

    for(int i=0; i<n; i++) {
        // 每行第一个数是矩阵单元格填充的数字
        int num;
        scanf("%d", &num);

        // 将空格获取掉
        getchar();

        // 定义一个链表，记录该num数字图形的所有点坐标
        LinkedList* link = new_LinkedList();

        // 获取点坐标
        int x, y;
        while(scanf("%d %d", &x, &y)) {
            // 点坐标位置填充对应数字
            matrix[x][y] = num;
            // 将该点坐标加入链表缓存
            add_LinkedList(link, x, y);
            if(getchar() != ' ') break;
        }

        // 初始化该num数字图形的周长为0
        res[i] = 0;

        // 取出链表中缓存的点
        ListNode* cur = link->head;
        while(cur != NULL) {
            for(int j = 0; j < 4; j++) {
                int offsetX = offsets[j][0];
                int offsetY = offsets[j][1];

                int newX = cur->x + offsetX;
                int newY = cur->y + offsetY;

                // 1、如果该点的上、下、左、右位置 越界了
                // 2、如果该点上、下、左、右位置 没有越界，但是值不为num
                // 则当前图形周长+1
                if(newX < 0 || newX >= 64 || newY < 0 || newY >= 64 || matrix[newX][newY] != num) {
                    res[i]++;
                }
            }

            cur = cur->next;
        }
    }

    // 按照输入顺序打印各个图形的周长
    for(int i=0; i<n; i++) {
        printf("%d ", res[i]);
    }

    return 0;
}

LinkedList* new_LinkedList() {
    LinkedList* link = (LinkedList*) malloc(sizeof(LinkedList));
    link->size = 0;
    link->head = NULL;
    link->tail = NULL;

    return link;
}

void add_LinkedList(LinkedList* link, int x, int y) {
    ListNode* node = (ListNode*) malloc(sizeof(ListNode));
    node->x = x;
    node->y = y;
    node->next = NULL;

    if(link->size == 0) {
        link->head = node;
        link->tail = node;
    } else {
        link->tail->next = node;
        link->tail = node;
    }

    link->size++;
}
